+    fn visual_rows(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_pane_plain_rows(),
+            PaneFocus::Right => {
+                let visible_right_content = self.visible_right_content(right_content);
+                let (width, _) = self.right_inner_size();
+                visual_text_rows(&visible_right_content, usize::from(width))
+            }
+        }
+    }
+
+    fn left_pane_plain_rows(&self) -> Vec<String> {
+        if !self.left_visible {
+            return Vec::new();
+        }
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut rows = vec![if self.control_selected == 0 {
+            "> work-leaf  command".to_string()
+        } else {
+            "  work-leaf  command".to_string()
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            rows.push(compact_agent_row(
+                agent,
+                self.control_selected == visible_position + 1,
+                inner_width,
+            ));
+            if !agent.modified_files.is_empty() {
+                rows.push(format!(
+                    "    files: {}",
+                    agent
+                        .modified_files
+                        .iter()
+                        .map(|path| path.display().to_string())
+                        .collect::<Vec<_>>()
+                        .join(", ")
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    rows.push(format!(
+                        "    {label}: {}",
+                        agents
+                            .iter()
+                            .map(AgentId::as_str)
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ));
+                }
+            }
+        }
+        rows
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, visible_right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let Some(inner) = self.visual_inner_rect(selection.pane) else {
+            return;
+        };
+        let rows = match selection.pane {
+            PaneFocus::Left => self.left_pane_plain_rows(),
+            PaneFocus::Right => visual_text_rows(visible_right_content, usize::from(inner.width)),
+        };
+        if rows.is_empty() {
+            return;
+        }
+        let height = usize::from(inner.height);
+        let width = usize::from(inner.width);
+        for row in 0..height {
+            for column in 0..width {
+                if visual_selection_contains(selection, row, column) {
+                    buffer
+                        .get_mut(
+                            inner.x.saturating_add(column as u16),
+                            inner.y.saturating_add(row as u16),
+                        )
+                        .modifier
+                        .insert(Modifier::REVERSED);
+                }
+            }
+        }
+    }
+
+    fn visual_inner_rect(&self, pane: PaneFocus) -> Option<Rect> {
+        let body_height = self.height.saturating_sub(1);
+        let layout = self.layout();
+        let pane_rect = match pane {
+            PaneFocus::Left if self.left_visible && layout.left_width > 0 => {
+                Rect::new(0, 0, layout.left_width, body_height)
+            }
+            PaneFocus::Left => return None,
+            PaneFocus::Right => Rect::new(layout.left_width, 0, layout.right_width, body_height),
+        };
+        let width = pane_rect.width.saturating_sub(2);
+        let height = pane_rect.height.saturating_sub(2);
+        (width > 0 && height > 0).then(|| {
+            Rect::new(
+                pane_rect.x.saturating_add(1),
+                pane_rect.y.saturating_add(1),
+                width,
+                height,
+            )
+        })
+    }
+
+    fn visual_inner_size(&self, pane: PaneFocus) -> (usize, usize) {
+        self.visual_inner_rect(pane)
+            .map(|rect| (usize::from(rect.width), usize::from(rect.height)))
+            .unwrap_or((1, 1))
+    }
